CREATE TABLE "plugin_wattanam_academic_management_enrollment_interval" ("id" TEXT PRIMARY KEY, "studentId" TEXT NOT NULL, "classId" TEXT NOT NULL, "validFrom" DATE NOT NULL, "validTo" DATE, "source" TEXT NOT NULL DEFAULT 'legacy-adoption', "createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "currentStudentId" TEXT GENERATED ALWAYS AS (CASE WHEN "validTo" IS NULL THEN "studentId" ELSE NULL END) STORED, CONSTRAINT "academic_enrollment_valid_range" CHECK ("validTo" IS NULL OR "validTo" >= "validFrom"), CONSTRAINT "academic_enrollment_natural_key" UNIQUE ("studentId", "classId", "validFrom"), CONSTRAINT "academic_enrollment_one_current" UNIQUE ("currentStudentId"));
